#!/usr/bin/env python3
# luxarch:handoffs hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Handoffs between the agents of one repo: the declared roles, the `agent:<role>` labels and the
`waiting_on` that hands work to another role. A hook imports them from here; the label rules
they build on are the ledger's (`luxpm_label`). Python 3.9 and the standard library only."""

from __future__ import annotations

import importlib
import re
import subprocess
import sys
import unicodedata
from pathlib import Path
from types import ModuleType

sys.path.insert(0, str(Path(__file__).parent))
from _ledger import (  # sibling helper, loaded by path
    _GIT_ERRORS,
    _LABEL_MAX,
    luxpm_label,
    state_dir,
)

# ── handoffs between the agents of one repo ──────────────────────────────────────────────────────
# A repo with more than one agent declares their roles in its committed `.luxarch.toml`:
# `[agents]` `roles = ["backend", "ios"]`. One agent hands work to another as an issue in the
# repo's own project labelled `agent:<their role>`, state todo, `waiting_on: "<their role> agent:
# <the step>"`; a reply owed on an existing issue is the same label and waiting_on. Each agent's
# `/fleet-start` lists the issues labelled with its role. The roles are read from the main
# checkout as committed at HEAD: a worktree's copy is the agent's own.
_HANDOFF_WAIT = re.compile(
    r"(?P<role>[A-Za-z0-9][A-Za-z0-9 _-]{0,40}?) agent:\s*\S.*", re.DOTALL
)
_ROLES_LINE = re.compile(r"^\s*roles\s*=\s*\[(?P<items>[^\]]*)\]", re.MULTILINE)


def role_name(raw: str) -> str:
    """A role as one word: lower-cased, spaces and underscores as `-` (`iOS app` -> `ios-app`)."""
    return re.sub(r"[\s_]+", "-", raw.strip().lower()).strip("-")


HANDOFF_LABEL = "agent:"
# LuxPM cuts a label at 50 characters, so a role's label fits only for a role of 44 or fewer
ROLE_MAX = _LABEL_MAX - len(HANDOFF_LABEL)
# characters that render blank yet are letters or symbols, so no category drops them
_FILLERS = frozenset("\u115f\u1160\u17b4\u17b5\u2800\u3164\uffa0")
# letters drawn like those of `agent` that NFKC leaves apart (Cyrillic, Greek, Armenian, IPA)
_LOOKALIKE = {
    "\u0430": "a",
    "\u0251": "a",
    "\u03b1": "a",
    "\u237a": "a",
    "\u0261": "g",
    "\u0581": "g",
    "\u0435": "e",
    "\u04bd": "e",
    "\u0578": "n",
    "\u057c": "n",
    "\u0442": "t",
    "\u03c4": "t",
}
_ROUTE_WORD = "agent"


def role_label(role: str) -> str:
    """The one spelling of a role's label: `agent:` and the role as `role_name` gives it. The
    queue each agent is told to list (`luxpm_list_issues(labels=[...])`, an exact match) and every
    check of a label sent both use it, so they cannot drift."""
    return HANDOFF_LABEL + role_name(role)


# what may stand between `agent` and the role of a route, once NFKC has folded the label: a colon
# or a colon lookalike, a hyphen or dash, an underscore, a space; a character the label is read
# through or a blank filler counts as one too
_ROUTE_SEPARATORS = frozenset(
    ":-_\u02d0\u02f8\u0589\u05c3\u1361\u2010\u2011\u2012\u2013\u2014\u2212\u2236"
    "\u2e2c\ua789\ufe13"
)
_INVISIBLE = ("Cf", "Cn", "Cc", "Co", "Cs")


def _unseen(c: str) -> bool:
    """`c` is read through or renders blank: a format, unassigned, control, private or surrogate
    character, or a blank filler."""
    return c in _FILLERS or unicodedata.category(c) in _INVISIBLE


def _route_split(label: object) -> tuple[str, str] | None:
    """(the first five letters, the rest) of the NFKC-folded, lower-cased label when those five
    letters are followed by a route separator (`_ROUTE_SEPARATORS`, a space, or a character
    `_unseen` reads through); None otherwise. Leading spaces and unseen characters are skipped,
    and combining marks and unseen characters inside the five letters are read through; each
    lookalike letter of `agent` is that letter."""
    text = unicodedata.normalize("NFKC", str(label or "")).lower()
    i = 0
    while i < len(text) and (text[i].isspace() or _unseen(text[i])):
        i += 1
    head = ""
    while i < len(text) and len(head) < len(_ROUTE_WORD):
        c = text[i]
        i += 1
        if _unseen(c) or unicodedata.category(c) in ("Mn", "Me"):
            continue
        head += _LOOKALIKE.get(c, c)
    while i < len(text) and unicodedata.category(text[i]) in ("Mn", "Me"):
        i += 1
    if len(head) < len(_ROUTE_WORD) or i >= len(text):
        return None
    sep = text[i]
    if not (sep in _ROUTE_SEPARATORS or sep.isspace() or _unseen(sep)):
        return None
    return head, text[i:]


def is_agent_label(label: object) -> bool:
    """The label reads as a route: once NFKC-folded (`_route_split`), it opens with the five letters
    of `agent`, each that letter or a letter outside ASCII and at least one the ASCII letter,
    followed by a separator. `agent:iOS`, `agent-ios`, `agent\uff1aios` and `\u0430gent:ios` read
    as one; `agents-guide`, `agentic` and `agent007` do not."""
    split = _route_split(label)
    if split is None:
        return False
    head = split[0]
    same = [head[i] == _ROUTE_WORD[i] for i in range(len(_ROUTE_WORD))]
    return any(same) and all(
        same[i] or (not head[i].isascii() and head[i].isalpha())
        for i in range(len(_ROUTE_WORD))
    )


def is_route(label: object, roles: list[str]) -> bool:
    """The label is exactly a declared role's route as LuxPM stores it: `luxpm_label` gives
    `role_label(<role>)` for a role in `roles`, and no character of it is unassigned in this
    Python's Unicode (LuxPM's own may keep one this Python drops)."""
    text = str(label or "")
    if any(unicodedata.category(c) == "Cn" for c in text):
        return False
    return luxpm_label(text) in {role_label(r) for r in roles}


def agent_label_role(label: object) -> str:
    """The role a label that reads as a route names, as `role_name` gives it: what follows
    `agent` and its separator (`agent:iOS`, `agent-ios` -> `ios`); '' for any other label."""
    split = _route_split(label)
    if split is None or not is_agent_label(label):
        return ""
    rest = "".join(
        c
        for c in split[1]
        if not _unseen(c) and unicodedata.category(c) not in ("Mn", "Me")
    )
    return role_name(re.sub(r"^[^0-9a-z]+", "", rest))


def raw_labels(raw: object) -> list[str] | None:
    """The labels a call sends, as sent (a comma-separated string read as its items); None when
    it sends none."""
    if isinstance(raw, str):
        return [x for x in raw.split(",") if luxpm_label(x)]
    if isinstance(raw, list):
        return [str(x) for x in raw]
    return None


def route_fault(raw: object, roles: list[str], refused: list[str] | None = None) -> str:
    """What is wrong with the routes a call sends (`raw`, its `labels`), '' when nothing: every
    label that reads as a route (`is_agent_label`) is exactly a declared role's
    (`is_route`), and there is one at most. The fault names the label to send."""
    labels = raw_labels(raw) or []
    listed = ", ".join(f"`{role_label(r)}`" for r in roles) if roles else "none"
    for label in labels:
        if not is_agent_label(label) or is_route(label, roles):
            continue
        role = agent_label_role(label)
        stored = luxpm_label(label)
        if role in roles:
            return (
                f"it sends `{stored}` ({ascii(label)}), which reads as a route and is not "
                f"one: LuxPM's label filter is exact, and the {role} agent's queue lists "
                f"`{role_label(role)}`. Write `agent:<role>` exactly. Send `{role_label(role)}`"
            )
        if role in (refused or []):
            return (
                f"it sends `{stored}`, for the role `{role}`, which this repo's `[agents] roles` "
                f"names but cannot route: LuxPM cuts a label at {_LABEL_MAX} characters, so a "
                f"role over {ROLE_MAX} has no label. The owner renames it in .luxarch.toml"
            )
        return (
            f"it sends `{stored}` ({ascii(label)}), which reads as a route to a role this repo "
            f"does not declare (the labels of its [agents] roles: {listed}): the issue would be "
            "in no declared agent's list. Write `agent:<role>` exactly, for a declared role"
        )
    routes = sorted({luxpm_label(x) for x in labels if is_route(x, roles)})
    if len(routes) > 1:
        return (
            f"it leaves {', '.join(routes)}: an open issue carries exactly one "
            "`agent:<role>`, the role whose agent works it next; LuxPM lists it under each, so "
            "two agents would work it"
        )
    return ""


def _toml() -> ModuleType | None:
    """The standard library's TOML reader (Python 3.11 and later), or None before it."""
    try:
        return importlib.import_module("tomllib")
    except ImportError:
        return None


def _all_roles() -> list[str]:
    """Every role `[agents] roles` names, each as `role_name` gives it; [] when none."""
    try:
        main = state_dir().parent
        shown = subprocess.run(
            ["git", "-C", str(main), "show", "HEAD:.luxarch.toml"],
            capture_output=True,
            text=True,
            timeout=4,
            check=False,
        )
    except _GIT_ERRORS:
        return []
    if shown.returncode != 0:
        return []
    roles = _roles_in(shown.stdout)
    return [r for r in (role_name(str(x)) for x in roles) if r]


def declared_roles() -> list[str]:
    """The agent roles the repo declares (`[agents] roles`), each as `role_name` gives it; []
    when none. A role over `ROLE_MAX` characters is refused (`refused_roles`): LuxPM would cut its
    label."""
    return [r for r in _all_roles() if len(r) <= ROLE_MAX]


def refused_roles() -> list[str]:
    """The roles `[agents] roles` names that are over `ROLE_MAX` characters: LuxPM cuts a label at
    50, so `role_label(<role>)` could never be stored, listed or matched."""
    return [r for r in _all_roles() if len(r) > ROLE_MAX]


def _roles_in(text: str) -> list[object]:
    """`[agents] roles` from the TOML text: read by the TOML reader where Python has one, else by
    the one-line form `roles = ["a", "b"]` under `[agents]` (Python 3.9 and 3.10, a Mac's own)."""
    toml = _toml()
    if toml is not None:
        try:
            data = toml.loads(text)
        except ValueError:
            return []
        agents = data.get("agents") if isinstance(data, dict) else None
        roles = agents.get("roles") if isinstance(agents, dict) else None
        return roles if isinstance(roles, list) else []
    section = re.search(
        r"^\[agents\]\s*$(?P<body>.*?)(?=^\[|\Z)", text, re.MULTILINE | re.DOTALL
    )
    m = _ROLES_LINE.search(section.group("body")) if section else None
    if not m:
        return []
    return re.findall(r"[\"']([^\"']*)[\"']", m.group("items"))


def handoff_to(waiting: object, own_role: str, roles: list[str]) -> str:
    """The role a `waiting_on` hands to (`<role> agent: <step>`) when it is a declared role other
    than this session's own, which must be declared too; '' otherwise."""
    m = _HANDOFF_WAIT.fullmatch(str(waiting or "").strip())
    own = role_name(own_role)
    if not m or not own or own not in roles:
        return ""
    role = role_name(m.group("role"))
    return role if role in roles and role != own else ""


def agent_role(name: str) -> str:
    """The role in `[<repo> <role>]`: the words after the first, without a `-` separator, joined
    by `-` and lower-cased (`[shop - luxarch]` -> `luxarch`). '' for a name of one word."""
    words = [w for w in name.strip().strip("[]").split() if w != "-"]
    return "-".join(w.lower() for w in words[1:])
